// TestTest262Syntax checks that every pattern Test262 requires to be a
// SyntaxError fails to compile, and that every pattern it requires to be
// valid compiles. As in TestTest262Generated, a valid pattern that does not
// compile is skipped unless TEST262_STRICT=1, while accepting an invalid
// pattern always fails.
func TestTest262Syntax(t *testing.T) {
	strict := os.Getenv("TEST262_STRICT") == "1"
	for _, tc := range test262SyntaxCases {
		t.Run(tc.name, func(t *testing.T) {
			if reason, skip := test262KnownFailures[tc.name]; skip {
				t.Skipf("known failure: %s", reason)
			}
			_, err := ecma262.CompileFlags(tc.pattern, tc.flags)
			switch {
			case !tc.valid && err == nil:
				t.Fatalf("%s: /%s/%s compiles, but it is a SyntaxError", tc.file, tc.pattern, tc.flags)
			case tc.valid && err != nil && strict:
				t.Fatalf("%s: /%s/%s does not compile: %v", tc.file, tc.pattern, tc.flags, err)
			case tc.valid && err != nil:
				t.Skipf("%s: /%s/%s does not compile: %v", tc.file, tc.pattern, tc.flags, err)
			}
		})
	}
}
